-- Uses ONLY synthetic commands generated by finance_test.sql on ephemeral PostgreSQL 17.
\set ON_ERROR_STOP on
DO $t$
DECLARE v jsonb; v_grant uuid;
BEGIN
 IF has_function_privilege('anon',
  'public.bil_admin_web_reconcile_subscription_command(uuid,text)','EXECUTE')
 OR has_function_privilege('authenticated',
  'public.bil_admin_web_reconcile_subscription_command(uuid,text)','EXECUTE')
 OR NOT has_function_privilege('service_role',
  'public.bil_admin_web_reconcile_subscription_command(uuid,text)','EXECUTE')
 THEN RAISE EXCEPTION 'RECEIPT_EXECUTABLE_BY_UNAUTHORIZED_ROLE'; END IF;

 SELECT (result->>'grant_id')::uuid INTO v_grant
   FROM bil_admin_private.subscription_commands
  WHERE actor_id='11111111-1111-4111-8111-111111111111'
    AND idempotency_key='grant-first-test-0001';
 v:=public.bil_admin_web_reconcile_subscription_command(
   '11111111-1111-4111-8111-111111111111','grant-first-test-0001');
 IF v->>'found'!='true' OR v->>'operation'!='grant'
   OR v->'receipt'->>'matched'!='true'
   OR v->'receipt'->>'changed'!='true'
   OR (v->'receipt'->>'grant_id')::uuid != v_grant
 THEN RAISE EXCEPTION 'GRANT_RECEIPT_READBACK_FAILED'; END IF;
 IF (SELECT count(*) FROM jsonb_object_keys(v)) != 3 THEN
    RAISE EXCEPTION 'RECEIPT_LEAKED_EXTRA_FIELDS'; END IF;

 v:=public.bil_admin_web_reconcile_subscription_command(
   '11111111-1111-4111-8111-111111111111','revoke-first-test-001');
 IF v->>'found'!='true' OR v->>'operation'!='revoke'
   OR v->'receipt'->>'matched'!='true'
   OR v->'receipt'->>'changed'!='true'
   OR (v->'receipt'->>'grant_id')::uuid != v_grant
 THEN RAISE EXCEPTION 'REVOKE_RECEIPT_READBACK_FAILED'; END IF;

 v:=public.bil_admin_web_reconcile_subscription_command(
   '11111111-1111-4111-8111-111111111111','not-found-test-0001');
 IF v != '{"found":false}'::jsonb THEN
   RAISE EXCEPTION 'MISSING_RECEIPT_MUST_STAY_UNCERTAIN'; END IF;
END $t$;
DO $t$
DECLARE blocked boolean:=false;
BEGIN
 BEGIN
  PERFORM public.bil_admin_web_reconcile_subscription_command(
   '33333333-3333-4333-8333-333333333333','grant-first-test-0001');
 EXCEPTION WHEN SQLSTATE '42501' THEN
  IF SQLERRM != 'administrator_required' THEN RAISE; END IF;
  blocked := true;
 END;
 IF NOT blocked THEN RAISE EXCEPTION 'REVIEWER_ACCESSED_ADMIN_RECEIPT'; END IF;
END $t$;
DO $t$
DECLARE blocked boolean:=false;
BEGIN
 PERFORM set_config('request.jwt.claims','{"role":"authenticated"}',true);
 BEGIN
  PERFORM public.bil_admin_web_reconcile_subscription_command(
   '11111111-1111-4111-8111-111111111111','grant-first-test-0001');
 EXCEPTION WHEN SQLSTATE '42501' THEN
  IF SQLERRM != 'administrator_required' THEN RAISE; END IF;
  blocked := true;
 END;
 PERFORM set_config('request.jwt.claims','{"role":"service_role"}',true);
 IF NOT blocked THEN RAISE EXCEPTION 'NON_SERVICE_ROLE_ACCESSED_RECEIPT'; END IF;
END $t$;
DO $t$
DECLARE blocked boolean:=false;
BEGIN
 BEGIN
  PERFORM public.bil_admin_web_reconcile_subscription_command(
   '11111111-1111-4111-8111-111111111111','bad');
 EXCEPTION WHEN SQLSTATE '22023' THEN blocked := true;
 END;
 IF NOT blocked THEN RAISE EXCEPTION 'SHORT_RECEIPT_KEY_ACCEPTED'; END IF;
END $t$;
DO $t$
BEGIN
 IF (SELECT count(*) FROM bil_admin_private.subscription_commands)!=2
 OR (SELECT count(*) FROM bil_admin_private.subscription_grants)!=1
 OR (SELECT count(*) FROM bil_admin_private.web_financial_step_up_receipts)!=2
 THEN RAISE EXCEPTION 'RECEIPT_READBACK_MUTATED_SYNTHETIC_STATE'; END IF;
END $t$;
SELECT 'PASS: financial reconciliation after interrupted grants and revokes; unauthorized access blocked; no changes' result;
